// ══════════════════════════════════════════════════════════════
// ABILITIES — generated hybrid / element-combo abilities
// Loaded in the background by ensureAbilitiesLoaded() (abilities.js).
// Every top-level statement here must be an `ABILITIES.<id> = {...}`
// assignment, and each id is defined exactly once (tests/data.test.js).
// ══════════════════════════════════════════════════════════════
ABILITIES.normal_normal_strike = {
  id:'normal_normal_strike', name:'Pure Strike', icon:'⚪',
  cost:12, costType:'mp', cooldown:0, maxCooldown:0, color:'#a8a878', element:'normal',
  desc:'A perfected basic attack. 160% ATK physical damage.',
  tags:['physical','normal'],
  use:(p,e)=>{
    const isCrit=rand(100)<p.stats.crit; const critMult=1.8+((p.stats.critDmg||0)/100);
    const dmg=Math.round(calcDmg(p.stats.atk*1.6,e.def)*(isCrit?critMult:1));
    dealDmgToEnemy(e,dmg,isCrit,false,false,'normal');
    return isCrit?`Pure Strike CRITS for ${dmg}!`:`Pure Strike deals ${dmg} damage.`;
  }
};

