ABILITIES.normal_normal_mastery = {
  id:'normal_normal_mastery', name:'Mastery Focus', icon:'🎯',
  cost:24, costType:'mp', cooldown:0, maxCooldown:3, color:'#a8a878', element:'normal',
  desc:'Pure concentration. +50% crit rate and +100% crit damage for 4 turns.',
  tags:['buff','normal'],
  use:(p,e)=>{
    addStatus(p,{id:'mastery_focus',name:'Mastery Focus',type:'buff',icon:'🎯',duration:4,
      onExpire:(pl)=>{pl.stats.crit=Math.max(0,pl.stats.crit-50); pl.stats.critDmg=(pl.stats.critDmg||0)-100;}});
    p.stats.crit+=50; p.stats.critDmg=(p.stats.critDmg||0)+100;
    return `Mastery Focus activated! +50% crit rate, +100% crit damage.`;
  }
};

