ABILITIES.normal_grass_sprout = {
  id:'normal_grass_sprout', name:'Sprout Strike', icon:'🌱',
  cost:12, costType:'mp', cooldown:0, maxCooldown:0, color:'#78c850', element:'grass',
  desc:'A simple strike that grows stronger. 150% ATK. Each use grants Growth stack (+5% damage).',
  tags:['physical','grass'],
  use:(p,e)=>{
    const isCrit=rand(100)<p.stats.crit; const critMult=1.5+((p.stats.critDmg||0)/100);
    const growthStacks=(p.status.find(s=>s.id==='growth')||{stacks:0}).stacks;
    const dmgMult=1.5*(1+(growthStacks*0.05));
    const dmg=Math.round(calcDmg(p.stats.atk*dmgMult,e.def)*(isCrit?critMult:1));
    dealDmgToEnemy(e,dmg,isCrit,false,false,'grass');
    const existing=p.status.find(s=>s.id==='growth');
    if(existing) existing.stacks++; else addStatus(p,{id:'growth',name:'Growth',type:'buff',icon:'🌱',duration:8,stacks:1});
    return isCrit?`Sprout Strike CRITS for ${dmg}! Growth +1.`:`Sprout Strike hits for ${dmg}. Growth +1.`;
  }
};

