    const isCrit=rand(100)<p.stats.crit; const critMult=1.8+((p.stats.critDmg||0)/100);
    const dmg=Math.round(calcDmg(p.stats.atk*2,e.def*0.5)*(isCrit?critMult:1));
    dealDmgToEnemy(e,dmg,isCrit,false,false,'cyber');
