ABILITIES.shadow_wind_cyclone_slash = {
  id:'shadow_wind_cyclone_slash', name:'Cyclone Slash', icon:'🌪️',
  cost:26, costType:'mp', cooldown:0, maxCooldown:2, color:'#aaddcc', element:'wind',
  desc:'A whirling shadow cyclone. 3 hits of 90% ATK wind. Each hit -5% enemy SPD.',
  tags:['physical','wind'],
  use:(p,e)=>{
    let total=0; let crits=0;
    for(let i=0;i<3;i++){
      const isCrit=rand(100)<p.stats.crit; const critMult=1.8+((p.stats.critDmg||0)/100);
      const dmg=Math.round(calcDmg(p.stats.atk*0.9,e.def)*(isCrit?critMult:1));
      dealDmgToEnemy(e,dmg,isCrit,false,false,'wind'); total+=dmg; if(isCrit) crits++;
      if(!e.maxSpd)e.maxSpd=e.spd; const spdPen=Math.round(e.spd*0.05); e.spd=Math.max(1,e.spd-spdPen);
    }
    return crits>0?`Cyclone Slash ${crits} CRITS for ${total}! Enemy SPD reduced.`:`Cyclone Slash spins for ${total}. Enemy SPD reduced.`;
  }
};

