ABILITIES.shadow_shadow_twin_strike = {
  id:'shadow_shadow_twin_strike', name:'Twin Shadow Strike', icon:'🗡️',
  cost:32, costType:'mp', cooldown:0, maxCooldown:3, color:'#220033', element:'shadow',
  desc:'Strike from two shadows simultaneously. 2 hits of 180% ATK shadow. Both guaranteed crit if vanished.',
  tags:['physical','shadow','crit'],
  use:(p,e)=>{
    const wasVanished=p.status&&p.status.some(s=>s.id==='vanished');
    let total=0; let crits=0;
    for(let i=0;i<2;i++){
      const isCrit=wasVanished||rand(100)<p.stats.crit; const critMult=2.0+((p.stats.critDmg||0)/100);
      const dmg=Math.round(calcDmg(p.stats.atk*1.8,e.def)*(isCrit?critMult:1));
      dealDmgToEnemy(e,dmg,isCrit,false,false,'shadow'); total+=dmg; if(isCrit) crits++;
    }
    return crits===2?`Twin Shadow Strike DOUBLE CRITS for ${total}!!!${wasVanished?' (Shadow crit!)':''}`:`Twin Shadow Strike hits for ${total}. ${crits} crit(s).`;
  }
};

