ABILITIES.normal_ice_slow = {
  id:'normal_ice_slow', name:'Slow', icon:'❄️',
  cost:20, costType:'mp', cooldown:0, maxCooldown:2, color:'#98d8d8', element:'ice',
  desc:'Slowing strike. 160% ATK. Slow for 3 turns.',
  tags:['physical','ice'],
  use:(p,e)=>{
    const isCrit=rand(100)<p.stats.crit; const critMult=1.8+((p.stats.critDmg||0)/100);
    const dmg=Math.round(calcDmg(p.stats.atk*1.6,e.def)*(isCrit?critMult:1));
    dealDmgToEnemy(e,dmg,isCrit,false,false,'ice');
    addStatus(e,{id:'slow',name:'Slow',type:'debuff',icon:'🐢',duration:3,onTurn:(en)=>{en.stats.spd=Math.max(1,Math.round(en.stats.spd*0.9));}});
    return isCrit?`Slow CRITS for ${dmg}!`:`Slow hits for ${dmg}.`;
  }
};

