ABILITIES.fire_space_plasma_burn = {
  id:'fire_space_plasma_burn', name:'Fire Plasma Burn', icon:'🔥',
  cost:22, costType:'mp', cooldown:0, maxCooldown:2, color:'#110033', element:'space',
  desc:'Fire Space attack. 160% ATK. Applies Displaced x2 for 4 turns.',
  tags:["physical","space","debuff"],
  use:(p,e)=>{
    const isCrit=rand(100)<p.stats.crit; const critMult=1.8+((p.stats.critDmg||0)/100);
    const dmg=Math.round(calcDmg(p.stats.atk*1.6,e.def)*(isCrit?critMult:1));
    dealDmgToEnemy(e,dmg,isCrit,false,false,'space');
    addStatus(e,{id:'displaced',name:'Displaced',type:'debuff',icon:'🌠',duration:4,stacks:2,
      onTurn:(en)=>{const dd=Math.max(1,Math.round(p.stats.atk*0.3*(en.status.find(s=>s.id==='displaced')||{stacks:1}).stacks));dealDmgToEnemy(en,dd,false,true,false,'space');}});
    return isCrit?`Plasma burn CRITS for ${dmg}! Displaced applied.`:`Plasma burn hits for ${dmg}. Displaced applied.`;
  }
};

ABILITIES.fire_space_galaxy_collapse = {
  id:'fire_space_galaxy_collapse', name:'Space Collapse', icon:'💥',
  cost:25, costType:'mp', cooldown:0, maxCooldown:3, color:'#110033', element:'space',
  desc:'Fire Space strike. 140% ATK. Reduces enemy DEF by 20%, applies Displaced.',
  tags:["physical","space","debuff"],
  use:(p,e)=>{
    const dmg=Math.round(calcDmg(p.stats.atk*1.4,e.def));
    dealDmgToEnemy(e,dmg,false,false,false,'space');
    const defPen=Math.round(e.def*0.2); e.def=Math.max(0,e.def-defPen);
    addStatus(e,{id:'displaced',name:'Displaced',type:'debuff',icon:'🌠',duration:3,stacks:1,
      onTurn:(en)=>{const dd=Math.max(1,Math.round(p.stats.atk*0.25));dealDmgToEnemy(en,dd,false,true,false,'space');}});
    return `Galaxy collapse hits for ${dmg}! -${defPen} DEF, Displaced.`;
  }
};

