ABILITIES.water_cosmic_collapse = {
  id:'water_cosmic_collapse', name:'Cosmic Collapse', icon:'💥',
  cost:25, costType:'mp', cooldown:0, maxCooldown:3, color:'#5533cc', element:'cosmic',
  desc:'Water Cosmic strike. 140% ATK. Reduces enemy DEF by 20%, applies Cosmic Burn.',
  tags:["physical","cosmic","debuff"],
  use:(p,e)=>{
    const dmg=Math.round(calcDmg(p.stats.atk*1.4,e.def));
    dealDmgToEnemy(e,dmg,false,false,false,'cosmic');
    const defPen=Math.round(e.def*0.2); e.def=Math.max(0,e.def-defPen);
    addStatus(e,{id:'cosmic_burn',name:'Cosmic Burn',type:'debuff',icon:'🌌',duration:3,stacks:1,
      onTurn:(en)=>{const dd=Math.max(1,Math.round(p.stats.atk*0.25));dealDmgToEnemy(en,dd,false,true,false,'cosmic');}});
    return `Collapse hits for ${dmg}! -${defPen} DEF, Cosmic Burn.`;
  }
};

